<div class="page-header"><div><p class="eyebrow">ACADEMIC FOUNDATION</p><h1>Academic configuration</h1><p>Create the reference data used by students, courses and registrations.</p></div></div>
<div class="settings-grid">
<section class="panel"><h2>Faculties</h2><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="faculty"><label class="form-label">Code<input class="form-control" name="code" placeholder="TECH" required maxlength="20"></label><label class="form-label">Faculty name<input class="form-control" name="name" placeholder="School of Technology" required maxlength="150"></label><button class="btn btn-primary mt-3">Add faculty</button></form><p class="form-hint mt-3"><?= count($faculties) ?> configured</p></section>
<section class="panel"><h2>Departments</h2><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="department"><label class="form-label">Faculty<select class="form-select" name="faculty_id"><?php foreach($faculties as $r):?><option value="<?= (int)$r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></label><label class="form-label">Code<input class="form-control" name="code" placeholder="SOFT" required maxlength="20"></label><label class="form-label">Name<input class="form-control" name="name" placeholder="Department of Software" required maxlength="150"></label><button class="btn btn-primary mt-3">Add department</button></form></section>
<section class="panel"><h2>Programmes</h2><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="programme"><label class="form-label">Department<select class="form-select" name="department_id"><?php foreach($departments as $r):?><option value="<?= (int)$r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></label><label class="form-label">Programme code<input class="form-control" name="code" placeholder="BSC-SWE" required maxlength="30"></label><label class="form-label">Name<input class="form-control" name="name" placeholder="Software Engineering" required maxlength="150"></label><button class="btn btn-primary mt-3">Add programme</button></form></section>
<section class="panel"><h2>Academic levels</h2><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="level"><label class="form-label">Level code<input class="form-control" name="code" placeholder="100" required maxlength="20"></label><label class="form-label">Name<input class="form-control" name="name" placeholder="100 Level" required maxlength="150"></label><label class="form-label">Sort order<input class="form-control" type="number" name="sort_order" min="1" required></label><button class="btn btn-primary mt-3">Add level</button></form></section>
<section class="panel"><h2>Academic session</h2><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="session"><label class="form-label">Session name<input class="form-control" name="name" placeholder="2026/2027" maxlength="9" required></label><label class="form-label">Starts on<input class="form-control" type="date" name="starts_on" required></label><label class="form-label">Ends on<input class="form-control" type="date" name="ends_on" required></label><button class="btn btn-primary mt-3">Create session</button></form>
<div class="stack mt-3"><?php foreach($sessions as $r):?><form method="post" action="/settings/academics" class="info-row"><?= csrf_field() ?><input type="hidden" name="action" value="activate_session"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><span><?= e($r['name'].' · '.$r['status']) ?></span><?php if($r['status']!=='active'):?><button class="btn btn-outline-primary btn-sm">Activate</button><?php endif; ?></form><?php endforeach; ?></div></section>
<section class="panel"><h2>Semesters</h2><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="semester"><label class="form-label">Academic session<select class="form-select" name="academic_session_id"><?php foreach($sessions as $r):?><option value="<?= (int)$r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></label><label class="form-label">Semester<select class="form-select" name="semester_number"><option value="1">First</option><option value="2">Second</option></select></label><label class="form-label">Starts on<input class="form-control" type="date" name="starts_on" required></label><label class="form-label">Ends on<input class="form-control" type="date" name="ends_on" required></label><label class="form-label">Registration deadline<input class="form-control" type="date" name="registration_deadline" required></label><button class="btn btn-primary mt-3">Create semester</button></form>
<div class="stack mt-3"><?php foreach($semesters as $r):?><form method="post" action="/settings/academics" class="info-row"><?= csrf_field() ?><input type="hidden" name="action" value="activate_semester"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><span><?= e($r['session_name'].' / '.$r['semester_number'].' · '.$r['status']) ?></span><?php if($r['status']!=='active'):?><button class="btn btn-outline-primary btn-sm">Activate</button><?php endif; ?></form><?php endforeach; ?></div></section></div>
<section class="panel mt-4"><div class="panel-heading"><h2>Manage existing academic records</h2><span class="subtle-tag">Edit · Deactivate · Reactivate</span></div>
<p class="form-hint">Deactivation preserves history. A record with dependent active records must be handled at the child level first.</p>
<?php foreach(['faculty'=>['Faculties',$faculties,'name'],'department'=>['Departments',$departments,'name'],'programme'=>['Programmes',$programmes,'name'],'level'=>['Academic levels',$levels,'name'],'session'=>['Academic sessions',$sessions,'name'],'semester'=>['Semesters',$semesters,'semester_number']] as $entity=>$group): ?>
<h3 class="mt-4"><?= e($group[0]) ?></h3><div class="table-scroll"><table class="table table-clean"><thead><tr><th>Record</th><th>Status</th><th>Manage</th></tr></thead><tbody>
<?php foreach($manage[$entity]['items'] as $record):?><tr><td><strong><?= e($entity==='semester'?$record['session_name'].' · Semester '.$record['semester_number']:$record[$group[2]]) ?></strong></td><td><span class="status-pill <?= $record['status']==='active'?'active':'inactive' ?>"><?= e($record['status']) ?></span></td><td><div class="inline-actions"><a href="/settings/academics/edit?entity=<?= e($entity) ?>&amp;id=<?= (int)$record['id'] ?>" class="btn btn-outline-primary btn-sm">Edit</a><form action="/settings/academics" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="entity" value="<?= e($entity) ?>"><input type="hidden" name="id" value="<?= (int)$record['id'] ?>"><input type="hidden" name="status" value="<?= $record['status']==='active'?'inactive':'active' ?>"><button class="btn btn-outline-secondary btn-sm"><?= $record['status']==='active'?'Deactivate':'Activate' ?></button></form></div></td></tr><?php endforeach;?>
</tbody></table></div><?php if(!$manage[$entity]['items']):?><p class="empty-state">No records configured.</p><?php endif;?>
<?php $pager=$manage[$entity];$pages=max(1,(int)ceil($pager['total']/PAGE_SIZE)); ?>
<nav class="paginationbar" aria-label="<?= e($group[0]) ?> pagination"><span>Page <?= (int)$pager['page'] ?> of <?= $pages ?> · <?= (int)$pager['total'] ?> records</span>
<?php if($pager['page']>1):?><a class="btn btn-outline-primary btn-sm" href="/settings/academics?<?= e($entity) ?>_page=<?= (int)$pager['page']-1 ?>">Previous</a><?php endif;?>
<?php if($pager['page']<$pages):?><a class="btn btn-primary btn-sm" href="/settings/academics?<?= e($entity) ?>_page=<?= (int)$pager['page']+1 ?>">Next</a><?php endif;?></nav>
<?php endforeach; ?></section>
